SCHEMA_DDL = ['CREATE TABLE IF NOT EXISTS records (id TEXT PRIMARY KEY,kind TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL)', 'CREATE INDEX IF NOT EXISTS records_kind ON records(kind,created_at)', 'CREATE TABLE IF NOT EXISTS experiments (id TEXT PRIMARY KEY,payload TEXT NOT NULL,current_revision TEXT,created_at TEXT NOT NULL)', 'CREATE TABLE IF NOT EXISTS receipts (operation_id TEXT PRIMARY KEY,request_hash TEXT NOT NULL,response TEXT NOT NULL)', 'CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY,experiment_id TEXT NOT NULL UNIQUE,state TEXT NOT NULL,lease_until TEXT,generation INTEGER NOT NULL DEFAULT 0,error TEXT)', 'CREATE TABLE IF NOT EXISTS events (seq INTEGER PRIMARY KEY AUTOINCREMENT,experiment_id TEXT NOT NULL,payload TEXT NOT NULL)', 'CREATE TABLE IF NOT EXISTS external_ownership (namespace TEXT NOT NULL,external_run_id TEXT NOT NULL,experiment_id TEXT NOT NULL REFERENCES experiments(id),case_id TEXT NOT NULL,request_hash TEXT NOT NULL,PRIMARY KEY(namespace,external_run_id))', 'CREATE TABLE IF NOT EXISTS record_links (owner_id TEXT NOT NULL REFERENCES records(id),target_id TEXT NOT NULL REFERENCES records(id),PRIMARY KEY(owner_id,target_id))', 'CREATE TRIGGER IF NOT EXISTS immutable_records BEFORE UPDATE ON records BEGIN SELECT RAISE(ABORT,"immutable record"); END', 'CREATE TRIGGER IF NOT EXISTS immutable_record_delete BEFORE DELETE ON records BEGIN SELECT RAISE(ABORT,"immutable record"); END']
